package com.neuralml.terminal.core

/**
 * Full mutable snapshot of every value the UI renders.
 *
 * The engine owns the state and updates it on the main thread at ~30 Hz; every
 * custom view only reads from it inside `onDraw`. Nothing here talks to a real
 * device, model or network — the values are generated by [SimulationEngine].
 */
class SimState {

    // ── top status bar ───────────────────────────────────────────────────────
    var clock: String = "00:00:00"
    var cpu: Float = 34.0f            // percent
    var npu: Float = 58.0f            // NPU inference load, percent
    var mem: Float = 47.0f            // percent
    var fps: Float = 58.0f            // ML inference FPS
    var signalBars: Int = 4           // 0..5
    var linkLabel: String = "SECURE LINK"
    var encrypted: Boolean = true

    // ── target biometrics ────────────────────────────────────────────────────
    var targetId: String = "TGT-7741-Δ"
    var alphaHz: Float = 10.4f
    var betaHz: Float = 18.6f
    var thetaHz: Float = 6.2f
    var deltaHz: Float = 2.4f
    var heartRate: Float = 76.0f      // BPM
    var gsr: Float = 6.4f             // µS
    var attention: Float = 84.0f      // percent
    var neuralActivity: Float = 71.0f // percent

    // ── ML engine status ─────────────────────────────────────────────────────
    var modelName: String = "NeuralDecoder-XL v3.7.2"
    var inferenceMode: String = "实时流式解码"
    var featureRate: Float = 92.4f    // percent
    var emotionConfidence: Float = 88.1f // percent
    var decodeAccuracy: Float = 96.4f // percent
    var iteration: Long = 184320L     // training / inference steps
    var loss: Float = 0.041f
    var latencyMs: Float = 14.0f
    var decodeModeKey: String = "standard"
    var decodeModeLabel: String = "标准"

    // ── central visualization ────────────────────────────────────────────────
    var neuroSync: Float = 91.0f      // 72..99 percent
    var decodeConfidence: Float = 87.5f // percent
    var waveGain: Float = 1.0f        // waveform amplitude multiplier
    var brainBoost: Float = 0.0f      // 0..1, extra brain-region activation
}
